static class QuickPreviewTests {
 static readonly List<string> checks=new List<string>();static string output;static void Check(bool ok,string label){if(!ok)throw new Exception(label);checks.Add(label);}
 static T Field<T>(object obj,string name){return (T)obj.GetType().GetField(name,BindingFlags.NonPublic|BindingFlags.Instance).GetValue(obj);}
 [STAThread]static void Main(string[] args){output=Path.GetFullPath(args[0]);Directory.CreateDirectory(output);Environment.SetEnvironmentVariable("JAGO_PREVIEW_CACHE",Path.Combine(output,"BrowserCache"));Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);var driver=new Form{ShowInTaskbar=false,WindowState=FormWindowState.Minimized};driver.Shown+=async(s,e)=>{try{await Run();File.WriteAllText(Path.Combine(output,"result.json"),"{\"ok\":true,\"checks\":"+new System.Web.Script.Serialization.JavaScriptSerializer().Serialize(checks)+"}");}catch(Exception error){File.WriteAllText(Path.Combine(output,"result.json"),new System.Web.Script.Serialization.JavaScriptSerializer().Serialize(new{ok=false,error=error.ToString(),checks=checks}));}finally{driver.Close();}};Application.Run(driver);}
 static async Task Run(){if(Environment.GetEnvironmentVariable("JAGO_PREVIEW_ONLY_EXPLORER_TEST")=="1"){await CheckExplorerSelection(Path.Combine(output,"sample.png"));return;}
 Check(ExplorerPreview.Eligible("CabinetWClass","DirectUIHWND",false,false),"Explorer file-list Space is eligible");foreach(var focus in new[]{"Edit","RichEditD2DPT","Microsoft.UI.Content.DesktopChildSiteBridge","ComboBox"})Check(!ExplorerPreview.Eligible("CabinetWClass",focus,false,false),"Typing focus ignored: "+focus);Check(!ExplorerPreview.Eligible("CabinetWClass","DirectUIHWND",true,false),"Rename caret excluded");Check(!ExplorerPreview.Eligible("CabinetWClass","DirectUIHWND",false,true),"Modified shortcuts preserved");Check(!ExplorerPreview.Eligible("OtherApp","DirectUIHWND",false,false),"Other apps excluded");Check(!new Preferences().FilePreviewEnabled,"Feature defaults off");
 Program.Config=Path.Combine(output,"Config");Program.Test=output;Program.Pipe="JagoPreviewTest-"+Guid.NewGuid();using(var companion=new Companion()){Check(Field<ExplorerPreview>(companion,"previewKeys")==null,"Disabled feature installs no hook");companion.SetFilePreview(true);Check(Field<ExplorerPreview>(companion,"previewKeys")!=null&&companion.store.Pref.FilePreviewEnabled,"Enable installs hook and saves state");companion.SetFilePreview(false);Check(Field<ExplorerPreview>(companion,"previewKeys")==null&&!new Store(Program.Config).Pref.FilePreviewEnabled,"Disable releases hook and persists");}
 string image=Path.Combine(output,"sample.png"),text=Path.Combine(output,"sample.txt"),md=Path.Combine(output,"sample.md"),unknown=Path.Combine(output,"sample.custom");using(var bmp=new Bitmap(640,360)){using(var g=Graphics.FromImage(bmp)){g.Clear(Color.FromArgb(36,54,57));using(var brush=new SolidBrush(Color.Goldenrod))g.FillEllipse(brush,100,40,280,280);g.DrawString("JAGO / file preview",new Font("Segoe UI",22),Brushes.White,30,280);}bmp.Save(image);}File.WriteAllText(text,"Preview text\r\nSecond line");File.WriteAllText(md,"# A little space to think\n\n**Creative notes**\n- Shape\n- Colour\n<script>alert('no')</script>");File.WriteAllText(unknown,"Some specialist format");
 PreviewProgram.Theme="Charcoal";using(var f=new QuickFilePreview(new[]{image,text,unknown,md,Path.Combine(output,"sample.pdf")})){f.Show();await Task.Delay(300);Check(!f.ShowInTaskbar,"No separate taskbar icon");Check(Field<Image>(f,"image").Width==640,"Image rendered at native dimensions");string renamed=image+".moved";File.Move(image,renamed);File.Move(renamed,image);Check(true,"Image preview does not lock source");using(var shot=new Bitmap(f.Width,f.Height)){f.DrawToBitmap(shot,new Rectangle(Point.Empty,shot.Size));shot.Save(Path.Combine(output,"image-preview.png"));}f.Navigate(1);Check(Field<Panel>(f,"content").Controls.OfType<RichTextBox>().Single().Text.Contains("Second line"),"Text preview displays file contents");f.Navigate(1);Check(Field<Panel>(f,"content").Controls.OfType<Label>().Single().Text.Contains("No inline preview"),"Unknown format offers clear fallback");f.Navigate(1);var doc=Field<Panel>(f,"content").Controls.OfType<QuickDocumentPreview>().Single();WebView2 browser=null;for(int i=0;i<100;i++){await Task.Delay(100);browser=Field<WebView2>(doc,"browser");if(browser!=null&&browser.CoreWebView2!=null&&browser.Source!=null)break;}Check(browser!=null&&browser.CoreWebView2!=null,"Offline Markdown renderer opens");await Task.Delay(1400);string rendered=await browser.CoreWebView2.ExecuteScriptAsync("document.body.innerText");File.WriteAllText(Path.Combine(output,"markdown-rendered.txt"),rendered);Check(rendered.Contains("A little space to think"),"Markdown contents actually rendered");Check(!browser.CoreWebView2.Settings.AreHostObjectsAllowed&&!browser.CoreWebView2.Settings.IsScriptEnabled,"Document scripts and host objects disabled");using(var stream=File.Create(Path.Combine(output,"markdown-preview.png")))await browser.CoreWebView2.CapturePreviewAsync(CoreWebView2CapturePreviewImageFormat.Png,stream);Check(QuickDocumentPreview.RenderMarkdown("<script>x</script>\n# Heading","Charcoal").Contains("&lt;script&gt;")&&QuickDocumentPreview.RenderMarkdown("# Heading","Charcoal").Contains("<h1>"),"Markdown styled and raw HTML escaped");
 if(File.Exists(Path.Combine(output,"sample.pdf"))){f.Navigate(1);doc=Field<Panel>(f,"content").Controls.OfType<QuickDocumentPreview>().Single();for(int i=0;i<100;i++){await Task.Delay(100);browser=Field<WebView2>(doc,"browser");if(browser!=null&&browser.CoreWebView2!=null&&browser.Source!=null&&browser.Source.IsFile)break;}await Task.Delay(1200);Check(browser.Source.IsFile&&browser.Source.LocalPath.EndsWith("sample.pdf"),"Local PDF viewer navigates to selected PDF");using(var stream=File.Create(Path.Combine(output,"pdf-preview.png")))await browser.CoreWebView2.CapturePreviewAsync(CoreWebView2CapturePreviewImageFormat.Png,stream);}
 for(int i=0;i<15;i++){f.Navigate(1);if(i%3==0)await Task.Delay(50);}Check(!f.IsDisposed,"Rapid preview navigation stays open");f.Close();}
 if(Environment.GetEnvironmentVariable("JAGO_PREVIEW_EXPLORER_TEST")=="1")await CheckExplorerSelection(image);
 using(var f=new QuickFilePreview(new[]{image})){f.Show();await Task.Delay(100);f.Size=new Size(480,360);f.PerformLayout();await Task.Delay(100);var toolbar=Field<FlowLayoutPanel>(f,"toolbar");Check(toolbar.Controls.Cast<Control>().All(c=>c.Bottom<=toolbar.ClientSize.Height),"Narrow preview wraps actions without clipping");foreach(var theme in new[]{"Sketchbook","Charcoal","Forest","Blueprint","Plum","Candy"}){CompanionPalette.Apply(f,theme);Check(f.BackColor.ToArgb()==CompanionPalette.For(theme)[0].ToArgb(),"Shared preview theme: "+theme);}f.Close();}
 string gif=Path.Combine(output,"sample.gif");if(File.Exists(gif))using(var f=new QuickFilePreview(new[]{gif})){f.Show();await Task.Delay(250);Check(ImageAnimator.CanAnimate(Field<Image>(f,"image")),"Animated GIF retains its animation frames");f.Close();}
 string wav=Path.Combine(output,"sample.wav");if(File.Exists(wav))using(var f=new QuickFilePreview(new[]{wav})){f.Show();for(int i=0;i<50;i++){await Task.Delay(100);var audio=Field<System.Windows.Controls.MediaElement>(f,"media");if(audio.NaturalDuration.HasTimeSpan)break;}Check(Field<System.Windows.Controls.MediaElement>(f,"media").NaturalDuration.HasTimeSpan,"Audio preview decodes WAV");f.Close();}
 string large=Path.Combine(output,"large.txt");using(var stream=File.Create(large))stream.SetLength(300000);bool rejected=false;try{QuickFilePreview.ReadBounded(large,256*1024);}catch(IOException){rejected=true;}Check(rejected,"Oversized text is bounded before loading");
 string clip=Path.Combine(output,"seek-fixture.mp4");if(File.Exists(clip)){using(var f=new QuickFilePreview(new[]{clip,image})){f.Show();for(int i=0;i<100;i++){await Task.Delay(100);var media=Field<System.Windows.Controls.MediaElement>(f,"media");if(media!=null&&media.NaturalDuration.HasTimeSpan)break;}var m=Field<System.Windows.Controls.MediaElement>(f,"media");Check(m.NaturalDuration.HasTimeSpan,"Video preview decodes MP4");f.Navigate(1);await Task.Delay(200);Check(Field<System.Windows.Controls.MediaElement>(f,"media")==null&&Field<Image>(f,"image")!=null,"Switching away closes media and opens image");f.Close();}}
 }
 static object Com(object target,string name,bool method,params object[] args){return target.GetType().InvokeMember(name,method?BindingFlags.InvokeMethod:BindingFlags.GetProperty,null,target,args);}
 static async Task CheckExplorerSelection(string image){object shell=null,windows=null,owned=null;var objects=new List<object>();try{System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo("explorer.exe","/n,\""+output+"\""){WindowStyle=System.Diagnostics.ProcessWindowStyle.Hidden});shell=Activator.CreateInstance(Type.GetTypeFromProgID("Shell.Application"));objects.Add(shell);windows=Com(shell,"Windows",true);objects.Add(windows);object document=null;for(int attempt=0;attempt<60&&owned==null;attempt++){await Task.Delay(100);int count=Convert.ToInt32(Com(windows,"Count",false));for(int i=0;i<count;i++){var window=Com(windows,"Item",true,i);objects.Add(window);try{var doc=Com(window,"Document",false);objects.Add(doc);var folder=Com(doc,"Folder",false);objects.Add(folder);var self=Com(folder,"Self",false);objects.Add(self);if(String.Equals(Convert.ToString(Com(self,"Path",false)),output,StringComparison.OrdinalIgnoreCase)){owned=window;document=doc;break;}}catch{}}}if(owned==null)throw new Exception("Test Explorer folder did not open");Com(document,"SelectItem",true,image,29);await Task.Delay(250);var hwnd=new IntPtr(Convert.ToInt64(Com(owned,"HWND",false)));Check(ExplorerPreview.Selection(hwnd).Any(p=>String.Equals(p,image,StringComparison.OrdinalIgnoreCase)),"Real Explorer selected-file extraction works");var oldForeground=GetForegroundWindow();ShowWindow(hwnd,5);SetForegroundWindow(hwnd);await Task.Delay(300);bool routed=false;using(var owner=new Form()){owner.CreateControl();var handle=owner.Handle;using(var keys=new ExplorerPreview(owner,paths=>routed=paths.Any(p=>String.Equals(p,image,StringComparison.OrdinalIgnoreCase)))){IntPtr data=System.Runtime.InteropServices.Marshal.AllocHGlobal(24);try{for(int k=0;k<24;k++)System.Runtime.InteropServices.Marshal.WriteByte(data,k,0);System.Runtime.InteropServices.Marshal.WriteInt32(data,32);var beforeFocus=GetForegroundWindow();var handled=(IntPtr)keys.GetType().GetMethod("Key",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(keys,new object[]{0,new IntPtr(0x100),data});for(int k=0;k<40&&!routed;k++)await Task.Delay(100);keys.GetType().GetMethod("Key",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(keys,new object[]{0,new IntPtr(0x101),data});Check(routed,"Focused Explorer Space callback routes selected file (target="+hwnd+", before="+beforeFocus+", after="+GetForegroundWindow()+", handled="+handled+")");}finally{System.Runtime.InteropServices.Marshal.FreeHGlobal(data);}}}if(GetForegroundWindow()==hwnd)SetForegroundWindow(oldForeground);}finally{if(owned!=null)try{Com(owned,"Quit",true);}catch{}for(int i=objects.Count-1;i>=0;i--)if(System.Runtime.InteropServices.Marshal.IsComObject(objects[i]))try{System.Runtime.InteropServices.Marshal.ReleaseComObject(objects[i]);}catch{}}}

